static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    int firstDayOfMonth = 1;
    int lastDayOfMonth = getDaysInMonth(year, month);

    int adjustedDay = firstDayOfMonth + (day - firstDayOfMonth) / dayStep * dayStep;
    if (adjustedDay > lastDayOfMonth(year, month)) {
        return lastDayOfMonth(year, month);
    }
    return adjustedDay;
}

private static int getDaysInMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) ? 29 : 28;
        default:
            throw new IllegalArgumentException("Invalid month: " + month);
    }
}

private static int lastDayOfMonth(int year, int month) {
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            return 31;
        case 4: case 6: case 9: case 11:
            return 30;
        case 2:
            return (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) ? 29 : 28;
        default:
            throw new IllegalArgumentException("Invalid month: " + month);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            size += 4;
            i++; // Skip the low surrogate
        } else {
            size += 3;
        }
    }
    return size;
}

