public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            ensureCapacity(byteLength);
            Arrays.fill(data, size, size + byteLength, (byte) 0);
        } else {
            ensureCapacity(byteLength);
            System.arraycopy(byteArrayValue, byteOffset, data, 0, byteLength);
        }
        size += byteLength;
        return this;
    }

    private void ensureCapacity(int additionalCapacity) {
        int newCapacity = Math.max(data.length * 2, size + additionalCapacity);
        data = Arrays.copyOf(data, newCapacity);
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byte[] byteArray = {1, 2, 3, 4, 5};
        byteVector.putByteArray(byteArray, 1, 3);
        System.out.println(Arrays.toString(byteVector.data));
