public class BufferManager {
    private List<ByteBuffer> buffers;

    public BufferManager() {
        this.buffers = new ArrayList<>();
    }

    public void addBuffer(ByteBuffer buffer) {
        this.buffers.add(buffer);
    }

    public byte[] toByteArray() {
        int totalSize = 0;
        for (ByteBuffer buffer : buffers) {
            totalSize += buffer.remaining();
        }

        byte[] result = new byte[totalSize];
        int position = 0;
        for (ByteBuffer buffer : buffers) {
            int length = buffer.remaining();
            buffer.get(result, position, length);
            position += length;
        }

        return result;
    }
}

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class StringUtils {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }
        StringBuilder out = new StringBuilder();
        Matcher m = Pattern.compile("\\\\(\\p{XDigit}{1,4}|.)").matcher(str);
        int lastMatchEnd = 0;
        while (m.find()) {
            out.append(str, lastMatchEnd, m.start());
            char decodedChar = (char) Integer.parseInt(m.group(1), 16);
            out.append(decodedChar);
            lastMatchEnd = m.end();
        }
        out.append(str.substring(lastMatchEnd));
        return out.toString();
    }
}

