protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    V startVertex = graph.getEdgeSource(tour.iterator().next());
    DijkstraShortestPath<V, E> dijkstra = new DijkstraShortestPath<>(graph);
    GraphPath<V, E> path = dijkstra.getPath(startVertex, startVertex);

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (path.getEndVertex().equals(source)) {
            path = dijkstra.getPath(path.getEndVertex(), target);
        } else if (path.getEndVertex().equals(target)) {
            path = dijkstra.getPath(path.getEndVertex(), source);
        } else {
            throw new IllegalArgumentException("Tour edges are not connected");
        }
    }

    return path;
}

